                'infographic_url' => 'field-agent-gps-audit',
                'audio_tracks' => [
                    'en' => '../academy_uploads/audio/field-agent-verification-en.mp3',
                    'pcm' => '../academy_uploads/audio/field-agent-verification-pcm.mp3',
